"""navera_lite/guard.py — the GPS guards: the jump gate (you wrote its core in mission 01). Part of NAVERA
Lite, the course's teaching stack (given in mission 09; mission 30 adds the cross-check with vision).
Written for the course; it is not NAVERA code.

The jump gate refuses a GPS fix farther from the last TRUSTED fix than the vehicle could have moved:
max_speed_mps × elapsed + gps_jump_margin_m (lesson 1 §5). A refused fix never becomes trusted, so a
spoofer who jumps far away stays refused until the vehicle could really be there.
"""
import math

from navera_lite.geo import enu_flat


# from mission 09 — finished: read it, use it, do not change it
def gate_ok(last_xy, new_xy, elapsed_s, v_max_mps, margin_m):
    """The jump gate of mission 01 (beacons.py TODO 7): True if new_xy is close enough to last_xy.

    last_xy, new_xy: (x, y) in metres; elapsed_s: seconds between them (a negative value counts as 0).
    Accepted when the distance ≤ v_max_mps × elapsed_s + margin_m.
    Example: gate_ok((0, 0), (120, 0), 1.0, 100.0, 50.0) → True;  gate_ok((0, 0), (500, 0), 1.0, 100.0, 50.0) → False
    """
    d = math.hypot(new_xy[0] - last_xy[0], new_xy[1] - last_xy[1])
    return d <= v_max_mps * max(0.0, elapsed_s) + margin_m


# from mission 09 — finished: read it, use it, do not change it
class JumpGate:
    """The jump gate on real positions: it keeps the last trusted GPS fix and judges each new one.

    cfg: the settings (max_speed_mps, gps_jump_margin_m). check(est) → (ok, reason); an accepted fix
    becomes the new trusted one, a refused one changes nothing.
    Example: g = JumpGate(DEFAULTS); g.check(Estimate("gps", 35.8256, 10.6084, 0.0)) → (True, "first fix");
             then a fix 5 km away 1 s later → (False, "jump 5000 m > 150 m in 1.0 s")
    """

    def __init__(self, cfg):
        self.v_max_mps = float(cfg["max_speed_mps"])
        self.margin_m = float(cfg["gps_jump_margin_m"])
        self.trusted = None            # the last trusted Estimate, None before the first fix

    def check(self, est):
        if self.trusted is None:
            self.trusted = est
            return True, "first fix"
        last = self.trusted
        e, n = enu_flat(last.lat, last.lon, est.lat, est.lon)
        elapsed = est.stamp_s - last.stamp_s
        if gate_ok((0.0, 0.0), (e, n), elapsed, self.v_max_mps, self.margin_m):
            self.trusted = est
            return True, "within the gate"
        allowed = self.v_max_mps * max(0.0, elapsed) + self.margin_m
        return False, f"jump {math.hypot(e, n):.0f} m > {allowed:.0f} m in {elapsed:.1f} s"

    def reset(self):
        """Forget the trusted fix (the next fix is accepted as the first one)."""
        self.trusted = None
